<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Support\Facades\DB;
class AuthenticateApiClient {public function handle($request,Closure $next,$scope=null){$token=$request->bearerToken();if(!$token)return response()->json(['error'=>'API token is required.'],401);$client=DB::table('api_clients')->where('token_hash',hash('sha256',$token))->where('is_active',1)->first();if(!$client)return response()->json(['error'=>'API token is invalid or disabled.'],401);$scopes=(array)json_decode($client->scopes,true);if($scope&&!in_array($scope,$scopes,true))return response()->json(['error'=>'This API key does not have the required scope.'],403);DB::table('api_clients')->where('id',$client->id)->update(['last_used_at'=>now(),'last_ip_hash'=>hash_hmac('sha256',(string)$request->ip(),config('app.key')),'updated_at'=>now()]);$request->attributes->set('api_client',$client);return $next($request);}}
